import{_ as c,o as i,c as r,a5 as a,j as n,a as e,t as o}from"./chunks/framework.BfQ7H7Qx.js";const b=JSON.parse('{"title":"Thiết kế DA-568: Động cơ Phát hiện Đột biến Xu hướng (Temporal Burst & BM25 Pruning)","description":"","frontmatter":{},"headers":[],"relativePath":"ai-models/trend-prediction-bm25-design.md","filePath":"ai-models/trend-prediction-bm25-design.md"}'),h={name:"ai-models/trend-prediction-bm25-design.md"};function d(g,t,l,s,u,p){return i(),r("div",null,[t[16]||(t[16]=a('<h1 id="thiet-ke-da-568-đong-co-phat-hien-đot-bien-xu-huong-temporal-burst-bm25-pruning" tabindex="-1">Thiết kế DA-568: Động cơ Phát hiện Đột biến Xu hướng (Temporal Burst &amp; BM25 Pruning) <a class="header-anchor" href="#thiet-ke-da-568-đong-co-phat-hien-đot-bien-xu-huong-temporal-burst-bm25-pruning" aria-label="Permalink to &quot;Thiết kế DA-568: Động cơ Phát hiện Đột biến Xu hướng (Temporal Burst &amp; BM25 Pruning)&quot;">​</a></h1><p>&gt; <a href="./../">&lt;&lt; Knowledge Base Home</a> · <a href="./README.html">AI Models &amp; Research</a> · <a href="./../architecture/ai-service-architecture.html">AI Service Architecture</a></p><h2 id="_1-tong-quan-hai-vai-tro-cua-thuat-toan-phat-hien-đot-bien-bm25" tabindex="-1">1. Tổng quan Hai Vai trò của Thuật toán Phát hiện Đột biến &amp; BM25 <a class="header-anchor" href="#_1-tong-quan-hai-vai-tro-cua-thuat-toan-phat-hien-đot-bien-bm25" aria-label="Permalink to &quot;1. Tổng quan Hai Vai trò của Thuật toán Phát hiện Đột biến &amp; BM25&quot;">​</a></h2><p>Trong <code>brandhub-ai-service</code>, mô hình thống kê tần suất từ khóa và Okapi BM25 đảm nhiệm <strong>2 nhiệm vụ tách biệt</strong> ở hai luồng Offline và Online:</p><ol><li><strong>Offline Trend Pipeline (<code>T4_BurstStep</code> — <code>app/services/pipeline/steps/t4_burst_step.py</code>)</strong>: Chấm điểm đột biến đa tín hiệu (<strong>Density Spike + Temporal Velocity + Author/Source Coverage + Multi-Reaction Engagement</strong>) trên tập cụm từ khóa &amp; thực thể tiếng Việt để phát hiện các xu hướng bùng nổ thật sự và sinh chuỗi thời gian (<code>velocity</code>, <code>acceleration</code>).</li><li><strong>Online Hybrid GraphRAG (<code>BM25 Scoring &amp; Context Pruning</code>)</strong>: Chấm điểm độ tương quan Okapi BM25 giữa câu truy vấn đã chuẩn hóa của người dùng và các node/chunk thu được từ ChromaDB + Neo4j (1–2 hops) để cắt tỉa 30%–40% ngữ cảnh nhiễu trước khi gửi vào LLM.</li></ol><hr><h2 id="_2-kien-truc-t4-burststep-trong-production-t4-burst-step-py" tabindex="-1">2. Kiến trúc <code>T4_BurstStep</code> trong Production (<code>t4_burst_step.py</code>) <a class="header-anchor" href="#_2-kien-truc-t4-burststep-trong-production-t4-burst-step-py" aria-label="Permalink to &quot;2. Kiến trúc `T4_BurstStep` trong Production (`t4_burst_step.py`)&quot;">​</a></h2><h3 id="_2-1-mo-rong-cum-tu-bang-khop-thuc-the-cheo-ner-cross-post-backfill" tabindex="-1">2.1 Mở rộng Cụm từ bằng Khớp Thực thể Chéo (<code>NER Cross-Post Backfill</code>) <a class="header-anchor" href="#_2-1-mo-rong-cum-tu-bang-khop-thuc-the-cheo-ner-cross-post-backfill" aria-label="Permalink to &quot;2.1 Mở rộng Cụm từ bằng Khớp Thực thể Chéo (`NER Cross-Post Backfill`)&quot;">​</a></h3><p>Đầu vào của <code>BurstStep</code> là danh sách <code>ctx.keyphrases</code> và <code>ctx.ner_entities</code> từ bước <code>T2_NLPStep</code>:</p><ul><li>Các thực thể thuộc nhóm <code>ENTITY_TYPES = {&quot;person&quot;, &quot;org&quot;, &quot;location&quot;, &quot;product&quot;, &quot;event&quot;}</code> có độ dài <code>&gt;= 3</code> ký tự (bao gồm cả mã sản phẩm 1 từ như <code>&quot;vf3&quot;</code>) nếu được NER nhận diện ở <strong>tối thiểu 2 bài viết độc lập (<code>posts &gt;= 2</code>)</strong> sẽ được biên dịch thành biểu thức chính quy ranh giới từ (<code>(?&lt;!\\w)...(?!\\w)</code>).</li><li>Hệ thống quét ngược lại toàn bộ <code>raw_text</code> của lô bài đăng để gắn bổ sung thực thể đó vào những bài mà bộ NER bỏ sót. Ngưỡng <code>posts &gt;= 2</code> ngăn chặn triệt để lỗi một danh từ phổ thông bị gắn nhầm nhãn thực thể ở 1 bài rồi lan sang hàng trăm bài khác.</li></ul><h3 id="_2-2-cong-thuc-điem-đot-bien-4-tin-hieu-burststep-process" tabindex="-1">2.2 Công thức Điểm Đột Biến 4 Tín hiệu (<code>BurstStep.process</code>) <a class="header-anchor" href="#_2-2-cong-thuc-điem-đot-bien-4-tin-hieu-burststep-process" aria-label="Permalink to &quot;2.2 Công thức Điểm Đột Biến 4 Tín hiệu (`BurstStep.process`)&quot;">​</a></h3><p>Với mỗi cụm từ ứng viên <code>term</code> xuất hiện trong ít nhất <code>MIN_DF = 2</code> bài đăng, hệ thống gom nhóm số lượng bài theo từng ngày thu thập <code>cnt = [c_1, c_2, ..., c_k]</code> và tổng lượng tương tác đa cảm xúc <code>engagement(item)</code> (cộng toàn bộ 7 loại reaction <code>like/love/care/haha/wow/sad/angry</code> + <code>shares</code> + <code>comments_count</code>):</p><p>$$\\text{BurstScore}(t) = 1.0 \\cdot \\ln(1 + \\max(0, \\text{Density}(t))) + 0.5 \\cdot \\text{Velocity}(t) + 0.4 \\cdot \\text{Coverage}(t) + 0.6 \\cdot \\ln\\left(1 + \\frac{\\sum \\text{Engagement}(t)}{\\text{DF}(t)}\\right)$$</p><p>Trong đó 4 thành phần trọng số thực tế trong code (<code>DENSITY_W = 1.0</code>, <code>VELOCITY_W = 0.5</code>, <code>COVERAGE_W = 0.4</code>, <code>ENGAGE_W = 0.6</code>) được định nghĩa như sau:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Thành phần</th><th style="text-align:center;">Trọng số</th><th style="text-align:left;">Công thức trong <code>BurstStep</code></th><th style="text-align:left;">Ý nghĩa thực tiễn</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>_density(cnt)</code></strong></td><td style="text-align:center;"><code>1.0</code></td><td style="text-align:left;">Với chuỗi <code>&gt;= 3</code> ngày: Z-score của ngày cao điểm nhất <code>mx</code> so với trung bình <code>mu</code> và độ lệch chuẩn <code>sd</code> của các ngày còn lại <code>(mx - mu) / sd</code> (lọc bỏ các từ có <code>density &lt; MIN_BURST = 1.0</code>). Dưới 3 ngày dùng <code>float(max(cnt))</code>.</td><td style="text-align:left;">Bắt chính xác cú nhảy vọt đột ngột (spike) và loại bỏ các từ khóa phổ biến đều đặn hàng ngày.</td></tr><tr><td style="text-align:left;"><strong><code>_velocity(cnt)</code></strong></td><td style="text-align:center;"><code>0.5</code></td><td style="text-align:left;">Độ dốc trung bình chuẩn hóa: <code>((cnt[-1] - cnt[0]) / (len(cnt) - 1)) / (1 + mean(cnt))</code>.</td><td style="text-align:left;">Phân biệt xu hướng <strong>đang đi lên</strong> (<code>&gt; 0</code>) với xu hướng đã qua đỉnh và đang thoái trào (<code>&lt; 0</code>).</td></tr><tr><td style="text-align:left;"><strong><code>_coverage(idxs, items)</code></strong></td><td style="text-align:center;"><code>0.4</code></td><td style="text-align:left;"><code>ln(1 + unique_authors) + ln(1 + unique_sources)</code>.</td><td style="text-align:left;">Thưởng điểm cho chủ đề lan tỏa qua nhiều tác giả độc lập và xuất hiện đồng thời trên nhiều nền tảng (<code>TikTok</code>, <code>Facebook</code>, <code>Google Trends</code>).</td></tr><tr><td style="text-align:left;"><strong><code>eng</code> (Engagement)</strong></td><td style="text-align:center;"><code>0.6</code></td><td style="text-align:left;"><code>ln(1 + eng_sum[term] / df_t)</code>.</td><td style="text-align:left;">Bắt trúng các trào lưu meme/viral ngắn có ít bài đăng gốc nhưng mỗi bài thu hút hàng chục nghìn lượt thả haha/tim và chia sẻ.</td></tr></tbody></table><h3 id="_2-3-ket-xuat-chuoi-thoi-gian-đong-hoc-top-ts-50" tabindex="-1">2.3 Kết xuất Chuỗi Thời Gian Động học (<code>TOP_TS = 50</code>) <a class="header-anchor" href="#_2-3-ket-xuat-chuoi-thoi-gian-đong-hoc-top-ts-50" aria-label="Permalink to &quot;2.3 Kết xuất Chuỗi Thời Gian Động học (`TOP_TS = 50`)&quot;">​</a></h3><p>Đối với <strong>Top 50</strong> cụm từ có <code>BurstScore</code> cao nhất (<code>ctx.anomaly_scores</code>), <code>BurstStep</code> tính sẵn đạo hàm bậc 1 (<strong>Velocity</strong>: chênh lệch bài đăng giữa 2 ngày liên tiếp) và đạo hàm bậc 2 (<strong>Acceleration</strong>: gia tốc bùng nổ) lưu vào <code>ctx.time_series[term]</code> để truyền sang tầng chấm điểm lan truyền đồ thị Neo4j (<code>T6</code>) và hiển thị biểu đồ động lượng trên Dashboard.</p><hr><h2 id="_3-cong-thuc-okapi-bm25-cho-so-sanh-cua-so-lich-su-cat-tia-ngu-canh-graphrag" tabindex="-1">3. Công thức Okapi BM25 cho So sánh Cửa sổ Lịch sử &amp; Cắt tỉa Ngữ cảnh GraphRAG <a class="header-anchor" href="#_3-cong-thuc-okapi-bm25-cho-so-sanh-cua-so-lich-su-cat-tia-ngu-canh-graphrag" aria-label="Permalink to &quot;3. Công thức Okapi BM25 cho So sánh Cửa sổ Lịch sử &amp; Cắt tỉa Ngữ cảnh GraphRAG&quot;">​</a></h2>',19)),n("p",null,[t[0]||(t[0]=e("Bên cạnh ",-1)),t[1]||(t[1]=n("code",null,"BurstStep",-1)),t[2]||(t[2]=e(" theo chuỗi ngày, công thức ",-1)),t[3]||(t[3]=n("strong",null,"Okapi BM25",-1)),t[4]||(t[4]=e(" chuẩn (",-1)),t[5]||(t[5]=n("code",null,"k_1 = 1.5",-1)),t[6]||(t[6]=e(", ",-1)),t[7]||(t[7]=n("code",null,"b = 0.75",-1)),e(") được sử dụng khi đối chiếu tập tài liệu mục tiêu $T_{\\text{target"+o("}}")+"$ với kho nền lịch sử $T_{\\text{background"+o("}}")+"$ (30 ngày) và khi ",1),t[8]||(t[8]=n("strong",null,[e("cắt tỉa ngữ cảnh GraphRAG ("),n("code",null,"BM25 Context Pruning"),e(")")],-1)),t[9]||(t[9]=e(":",-1))]),n("p",null,"$$\\text{BM25}(D, Q) = \\sum_{q_i \\in Q} \\text{IDF}(q_i, T_{\\text{background"+o("}}")+") \\cdot \\frac{f(q_i, D) \\cdot (k_1 + 1)}{f(q_i, D) + k_1 \\cdot \\left(1 - b + b \\cdot \\frac{|D|}{\\text{avgdl"+o("}}")+"\\right)}$$",1),n("ul",null,[n("li",null,[t[10]||(t[10]=n("strong",null,"Trong luồng Offline (Windowed Anomaly Baseline):",-1)),e(" Từ khóa xuất hiện dày đặc trong 30 ngày trước có $\\text{IDF}(q_i, T_{\\text{background"+o("}}")+")$ thấp nên tự động bị triệt tiêu dù có $TF$ cao trong ngày (ví dụ: ",1),t[11]||(t[11]=n("code",null,'"khuyến mãi"',-1)),t[12]||(t[12]=e(", ",-1)),t[13]||(t[13]=n("code",null,'"freeship"',-1)),t[14]||(t[14]=e(").",-1))]),t[15]||(t[15]=n("li",null,[n("strong",null,[e("Trong luồng Online ("),n("code",null,"DA-AI03-04.2"),e(" — GraphRAG Pruning):")]),e(" Sau khi ChromaDB trả về các Entry Points và Neo4j duyệt mở rộng 1–2 bước nhảy ("),n("code",null,":KOL"),e(", "),n("code",null,":Dish"),e(", "),n("code",null,":Location"),e("), mô-đun Pruning tính điểm "),n("code",null,"BM25(node_context, normalized_user_query)"),e(" và loại bỏ các node lân cận dưới ngưỡng tương quan, giữ gói ngữ cảnh gửi sang Groq/Claude gọn nhẹ và chống ảo giác thông tin.")],-1))])])}const x=c(h,[["render",d]]);export{b as __pageData,x as default};
